-- CREATE 2026 Run of Show v3 (replaces prior run-of-show + narrative blocks).
do $$ declare pid uuid; did uuid; begin
  select id into pid from projects where name = 'CREATE 2026';
  if pid is null then raise notice 'CREATE 2026 not found'; return; end if;
  delete from ros_items where project_id = pid;
  delete from ros_days where project_id = pid;
  delete from internal_blocks where project_id = pid;
end $$;
