  insert into internal_blocks (project_id, section, value, sort_order) values (pid, 'meta', 'DRAFT v3 — updated Jul 16, 2026 with the Sunday setup/rehearsal, Monday/Tuesday staging, and the VIP dinner & lunch introduction strategy from the Jul 15–16 planning calls. Items marked ⚠ need confirmation.', 0);
  insert into internal_blocks (project_id, section, value, sort_order) values (pid, 'flags', 'Tue 9:15 AM double-booking: transcript lists both an Informa pre-meeting (Fernando/Juan/Nic, espresso) and a floor meeting with Marcus at the same time — confirm sequential vs. same event.', 0);
  insert into internal_blocks (project_id, section, value, sort_order) values (pid, 'flags', 'Monday main-stage intro time: transcript says 10:50–11:00 AM; Info Hub previously logged 11:10 AM — confirm exact time.', 1);
  insert into internal_blocks (project_id, section, value, sort_order) values (pid, 'flags', 'Operator session duration: transcript describes 12:00–12:45 PM (45 min); Info Hub logged 12:00–12:30 PM (30 min) — confirm if same session.', 2);
  insert into internal_blocks (project_id, section, value, sort_order) values (pid, 'flags', 'Departure day: Jul 16 transcript has the team departing Tuesday night after dinner at Bashi; booked flights/checkouts fall Wed Jul 22 — confirm actual departure timing.', 3);
  insert into internal_blocks (project_id, section, value, sort_order) values (pid, 'flags', 'Welcome Reception time: Jul 15 call referenced 6:00–8:00 PM; Day 1 schedule lists 5:00–7:15 PM — confirm actual window.', 4);
  insert into internal_blocks (project_id, section, value, sort_order) values (pid, 'flags', 'Top-4 client list for the Monday lunch floor-walk isn''t finalized — Toast and Momos are set, two more clients TBD.', 5);
  insert into internal_blocks (project_id, section, value, sort_order) values (pid, 'flags', 'Monday 2:45 PM break referenced on the Jul 15 call as a pickup window for remaining client intros — not on the published Day 1 schedule; confirm.', 6);
  insert into internal_blocks (project_id, section, value, sort_order) values (pid, 'flags', 'Floor plan for Nelson''s still needed (Fernando) ahead of the Sunday venue walkthrough.', 7);
  insert into internal_blocks (project_id, section, value, sort_order) values (pid, 'flags', 'Badge / Access: standard badge vs. alternative branding (Wi-Fi, key card) — decision pending with Marcus/JG.', 8);
  insert into internal_blocks (project_id, section, value, sort_order) values (pid, 'flags', 'WithCoverage debrief still not booked (outreach to Sage Disch); Axial Shift debrief date needs reconciling (roster said Jul 30, calendar shows Jul 28).', 9);
  insert into internal_blocks (project_id, section, value, sort_order) values (pid, 'keynotes', 'Hotel: 5 rooms at Terranea — all 5 team members booked, check-in Jul 19.', 0);
  insert into internal_blocks (project_id, section, value, sort_order) values (pid, 'keynotes', 'Side door (PV Ballroom 6) must stay locked at all times during the operator session — use a sign or physically block it if no lock is available.', 1);
  insert into internal_blocks (project_id, section, value, sort_order) values (pid, 'keynotes', 'Operator-only sessions are closed to all sponsors; any sponsor who attempts entry is redirected to the back table. A badge photo is taken of every person entering, framed as a secondary check-in.', 2);
  insert into internal_blocks (project_id, section, value, sort_order) values (pid, 'keynotes', 'Innovation Forum is BYOL — Fernando brings his own laptop for the breakout.', 3);
  insert into internal_blocks (project_id, section, value, sort_order) values (pid, 'keynotes', 'GRIP Speed Networking runs Tue 10:15 AM–12:45 PM at Palos Verdes Terrace — up to 10 meetings × 10 min per client company.', 4);
  insert into internal_blocks (project_id, section, value, sort_order) values (pid, 'keynotes', 'Post-event: video & photo deliverables from Informa expected within 90 days of close.', 5);
  insert into internal_blocks (project_id, section, label, value, sort_order) values (pid, 'roles', 'Fernando', 'Room setup/teardown, badge scanning at door, side-door lock, boards & AV breakdown/storage, Informa meetings, stays with Juan at VIP dinner, final room checks. Co-leads the Monday lunch floor walk with Beth (Momos, Toast, Reachify, Axial Shift); sources a floor plan for Nelson''s; scouts the venue Sunday evening.', 0);
  insert into internal_blocks (project_id, section, label, value, sort_order) values (pid, 'roles', 'Juan (JG)', 'Main presenter (rehearsal & live), walk-and-talk during lunch, Informa pre-meeting & midday meeting, main-stage intro of Chipotle CEO. At the VIP dinner his sole focus is brokering the pre-identified introductions — no unstructured mingling; the team keeps him on-task and redirects him to the bullpen as needed.', 1);
  insert into internal_blocks (project_id, section, label, value, sort_order) values (pid, 'roles', 'Nic', 'Badge scanning at door, client introductions, lunch-stand coverage at 12:20 PM, Informa pre-meeting, meeting with Marcus. Self-serves introductions at the dinner using his own relationships and helps keep Juan on task.', 2);
  insert into internal_blocks (project_id, section, label, value, sort_order) values (pid, 'roles', 'Beth & Caitlin', 'Client greeting and seating at arrival, client positioning/readiness pre-session, introductions throughout, sponsor management and redirection. For the VIP dinner, Caitlin owns WithCoverage, Buyer''s Edge & Meez; Fernando + Beth own Momos, Toast, Reachify & Axial Shift — each pair checks in with their clients Monday afternoon, marks off connections already made, and confirms the top 1–2 intro targets for that night.', 3);
  insert into internal_blocks (project_id, section, value, sort_order) values (pid, 'vip_strategy', 'Goal: 1–2 warm introductions per client at the VIP dinner. Internal target is to work through the full list within the first hour (by minute 59) while people are still arriving and warming up.', 0);
  insert into internal_blocks (project_id, section, value, sort_order) values (pid, 'vip_strategy', '14 names prepped in advance — top 2 targets per client plus 1 backup each in case of no-shows — briefed to Juan before the dinner. The point is names top of mind so he can flag concerns ahead of time.', 1);
  insert into internal_blocks (project_id, section, value, sort_order) values (pid, 'vip_strategy', 'Deprioritize a target if the client already has a scheduled 1:1 with them the next day at GRIP — unless the target is also a buyer-intent match and a must-meet, in which case pay it off early as a hedge against no-shows.', 2);
  insert into internal_blocks (project_id, section, value, sort_order) values (pid, 'vip_strategy', 'Bullpen workflow: Juan approaches a target first, alone, to start a natural conversation. A teammate then walks the assigned client over and makes the introduction. Juan exits naturally and resets at the bullpen for the next pairing.', 3);
  insert into internal_blocks (project_id, section, value, sort_order) values (pid, 'vip_strategy', 'Protecting Juan''s time is the team''s job — no unstructured mingling that night. Anyone can redirect him back to the bullpen if he gets pulled into an unrelated conversation.', 4);
  insert into internal_blocks (project_id, section, value, sort_order) values (pid, 'vip_strategy', 'Nic and Caitlin self-serve introductions where they have first-degree relationships — clients prefer an intro from someone who actually knows the target. Lean on Juan for harder connections; avoid saving everything for the final hour.', 5);
  insert into internal_blocks (project_id, section, value, sort_order) values (pid, 'vip_strategy', 'Client coaching happens verbally during the Monday afternoon check-in only — do not put the bullpen concept in written pre-event materials. Tell clients to mingle in a general area near the bullpen/food station; the team will come find them.', 6);
  insert into internal_blocks (project_id, section, value, sort_order) values (pid, 'vip_strategy', 'Lunch-window live walk (~1:00–1:45 PM, after the operator session runs long): rotate through top-priority clients for a 10–15 min guided walk each, making live floor introductions. Toast and Momos confirmed; 2 more TBD. KPI: minimum 1 intro per client; anyone not covered gets picked up at the next break or the Welcome Reception.', 7);
  insert into internal_blocks (project_id, section, value, sort_order) values (pid, 'vip_strategy', 'Venue: Nelson''s expected to be primarily outdoors with high-tops and tables, unlike last year''s congested indoor bar layout. The team scouts the space Sunday evening to plan the bullpen location.', 8);
  insert into ros_days (project_id, label, day_date, color, footnote, sort_order) values (pid, 'Sunday, July 19, 2026 — Arrival, Walkthrough & Rehearsal', null, '#BA7517', 'Day-of rules confirmed during the walkthrough: main entry only (all attendees enter through the main door at the bottom of the room); client arrival 11:15 AM (greeting before session), operator arrival 11:50 AM; session starts promptly at 12:00 PM day-of; Juan''s talk runs ~20–25 min; photographer will be in the room day-of (flagged here, not present for the walkthrough itself).', 0) returning id into did;
  insert into ros_items (project_id, day_id, time, duration, title, notes, flag, sort_order) values (pid, did, '3:00 PM', null, 'Team Meets — PV Ballroom 6', 'This is the session room for the operator/client program.', false, 0);
  insert into ros_items (project_id, day_id, time, duration, title, notes, flag, sort_order) values (pid, did, '3:00 – 4:00 PM', '~1 hr', 'Run of Show Walkthrough', 'Moderation flow, group presentation structure & workshop format reviewed. Fernando sets up boards, markers, stickers. AV stood up & tested. Juan (JG) runs full presentation. Team selects seating for operators, captains, and clients.', false, 1);
  insert into ros_items (project_id, day_id, time, duration, title, notes, flag, sort_order) values (pid, did, '4:00 PM', null, 'Connections Plan', 'Dial in on the plan for client connections — what happens during in-betweens and how clients get connected.', false, 2);
  insert into ros_items (project_id, day_id, time, duration, title, notes, flag, sort_order) values (pid, did, '4:30 PM', '30 min', 'Space Walkthrough', 'Walk the general session area, the terrace (tech meetings location), and review the tech stands.', false, 3);
  insert into ros_items (project_id, day_id, time, duration, title, notes, flag, sort_order) values (pid, did, '5:00 PM', null, 'Nelson''s', 'Scout the VIP Dinner venue ahead of Monday night — plan the bullpen area/layout. Last year''s setup made fetching clients on demand nearly impossible; Nelson''s expected to be primarily outdoors with high-tops and tables. Fernando to bring a floor plan if one can be sourced.', false, 4);
  insert into ros_items (project_id, day_id, time, duration, title, notes, flag, sort_order) values (pid, did, '5:30 PM', null, 'Happy Hour', null, false, 5);
  insert into ros_days (project_id, label, day_date, color, footnote, sort_order) values (pid, 'Monday, July 20, 2026 — Event Day Execution', null, '#185FA5', null, 1) returning id into did;
  insert into ros_items (project_id, day_id, time, duration, title, notes, flag, sort_order) values (pid, did, '8:00 AM – 2:00 PM', '6 hrs', 'Tech Stands Open', null, false, 0);
  insert into ros_items (project_id, day_id, time, duration, title, notes, flag, sort_order) values (pid, did, '8:00 AM', null, 'Event Opens', 'Team guides & prepares clients for incoming arrivals.', false, 1);
  insert into ros_items (project_id, day_id, time, duration, title, notes, flag, sort_order) values (pid, did, '9:05 AM', '~1 hr', 'Rehearsal — PV Ballroom 1', 'Juan runs full presentation; full team present.', false, 2);
  insert into ros_items (project_id, day_id, time, duration, title, notes, flag, sort_order) values (pid, did, '10:00 – 10:45 AM', '45 min', 'Conference Begins / Juan''s Solo Time', 'Juan has solo time on the main stage floor.', false, 3);
  insert into ros_items (project_id, day_id, time, duration, title, notes, flag, sort_order) values (pid, did, '10:00 AM (concurrent)', null, 'Breakout Room Final Check — PV Ballroom 6', 'Fernando confirms: boards centered on tables, all tables set, markers & stickers out, AV ready, caffeine loaded on presentation computer, door shut, team has cameras.', false, 4);
  insert into ros_items (project_id, day_id, time, duration, title, notes, flag, sort_order) values (pid, did, '10:40 – 10:50 AM', '10 min', 'Juan Mic''d Up', null, false, 5);
  insert into ros_items (project_id, day_id, time, duration, title, notes, flag, sort_order) values (pid, did, '10:50 – 11:00 AM', '10 min', 'Juan Main Stage Intro (Chipotle CEO)', 'Info Hub previously logged this as a single point at 11:10 AM.', true, 6);
  insert into ros_items (project_id, day_id, time, duration, title, notes, flag, sort_order) values (pid, did, '11:40 AM', '5 min', 'Team Staging — PV Ballroom 6', 'Full team assembles and takes positions. Fernando locks the side door and does a final readiness check.', false, 7);
  insert into ros_items (project_id, day_id, time, duration, title, notes, flag, sort_order) values (pid, did, '11:45 AM', null, 'Clients Arrive', 'Beth & Caitlin greet clients and get them seated; Nic & Fernando scan badges at the door. Once clients are settled, roles switch. Side door stays locked at all times. Operator-only — any sponsor who tries to enter is redirected to the back table. Badge photo taken of every entrant (secondary check-in).', false, 8);
  insert into ros_items (project_id, day_id, time, duration, title, notes, flag, sort_order) values (pid, did, '12:00 – 12:45 PM', '45 min', 'Operator Session (Innovation Forum Breakout)', 'Juan presents (~20–25 min). No sponsors until operators are mostly seated, then sponsors may sit at tables 9 & 10 (back only). Photographer in the room throughout. Info Hub previously logged this as a 30-min block; the Jul 15 call references it running to 12:45 (45-min reading).', true, 9);
  insert into ros_items (project_id, day_id, time, duration, title, notes, flag, sort_order) values (pid, did, '12:20 PM', null, 'Lunch Stand Coverage', 'Nic or Beth exits the session to cover the second-attendee position at the lunch stand.', false, 10);
  insert into ros_items (project_id, day_id, time, duration, title, notes, flag, sort_order) values (pid, did, '12:45 – 2:00 PM', '1 hr 15', 'Networking Lunch', 'Unstructured time in the Palos Verdes foyer (outdoor, adjacent to the ballroom). Because the operator session runs to 12:45, clients aren''t effectively free until ~1:00 PM, so the live-intro window runs closer to 1:00–1:45 PM. Juan walk-and-talk. Fernando pulls all boards + the AV computer to his room.', false, 11);
  insert into ros_items (project_id, day_id, time, duration, title, notes, flag, sort_order) values (pid, did, '1:00 – 1:45 PM', '45 min', 'Live Intro Rotation (Floor Walks)', 'Fernando, Beth & Caitlin rotate 10–15 min guided walks with top-priority clients, making live introductions. Toast & Momos confirmed; 2 more clients TBD. KPI: minimum 1 intro per client; remaining clients picked up at the next break or the Welcome Reception.', true, 12);
  insert into ros_items (project_id, day_id, time, duration, title, notes, flag, sort_order) values (pid, did, '12:45 PM – 5:00 PM', null, 'Client Connections', 'Ongoing through the afternoon. Includes the per-client afternoon check-in: each pair marks off connections made, confirms the top 1–2 intro targets for the VIP dinner, and verbally briefs clients on the ''bullpen'' approach. Verbal only — not documented in written pre-event materials.', false, 13);
  insert into ros_items (project_id, day_id, time, duration, title, notes, flag, sort_order) values (pid, did, '5:00 – 7:15 PM', '~2 hrs', 'Welcome Reception', 'Continue making introductions. Jul 15 call referenced a 6:00–8:00 PM window — confirm actual time.', true, 14);
  insert into ros_items (project_id, day_id, time, duration, title, notes, flag, sort_order) values (pid, did, '7:00 – 9:00 PM', '2 hrs', 'VIP Dinner @ Nelson''s', 'Juan runs the bullpen introduction workflow — goal of 1–2 warm intros per client, ideally complete within the first hour. Fernando stays with Juan throughout; Caitlin, Beth & Nic identify targets and move Juan into conversations. 4 tickets for 858 team + 1 per client company; check-in via Luma.', false, 15);
  insert into ros_items (project_id, day_id, time, duration, title, notes, flag, sort_order) values (pid, did, '9:00 PM', null, 'Night Ends', null, false, 16);
  insert into ros_days (project_id, label, day_date, color, footnote, sort_order) values (pid, 'Tuesday, July 21, 2026 — Final Day & Closeout', null, '#534AB7', null, 2) returning id into did;
  insert into ros_items (project_id, day_id, time, duration, title, notes, flag, sort_order) values (pid, did, '7:00 AM – 3:30 PM', '8.5 hrs', 'Tech Stands Open', 'Team should be on the conference floor by 7:00 AM.', false, 0);
  insert into ros_items (project_id, day_id, time, duration, title, notes, flag, sort_order) values (pid, did, '7:15 – 8:00 AM', '45 min', 'Breakfast', null, false, 1);
  insert into ros_items (project_id, day_id, time, duration, title, notes, flag, sort_order) values (pid, did, '8:00 – 10:00 AM', '2 hrs', 'Client Introductions & Support', 'Caitlin, Nic, Fernando continue introductions and support clients on the floor.', false, 2);
  insert into ros_items (project_id, day_id, time, duration, title, notes, flag, sort_order) values (pid, did, '9:15 – 9:45 AM', '30 min', 'Informa Pre-Meeting (Espresso)', 'Fernando, Juan, Nic. Transcript also places them on the floor at 9:15 AM meeting with Marcus during 1:1 group meetings — confirm sequential or same event.', true, 3);
  insert into ros_items (project_id, day_id, time, duration, title, notes, flag, sort_order) values (pid, did, '10:15 AM – 12:45 PM', '2.5 hrs', 'GRIP Speed Networking', 'Palos Verdes Terrace — up to 10 mtgs × 10 min + 5 min break. Likely the ''one-on-one group meetings'' referenced with Marcus above.', false, 4);
  insert into ros_items (project_id, day_id, time, duration, title, notes, flag, sort_order) values (pid, did, '12:00 PM', null, 'Fernando & Juan × Informa Meeting', null, false, 5);
  insert into ros_items (project_id, day_id, time, duration, title, notes, flag, sort_order) values (pid, did, '12:45 – 2:00 PM', '1 hr 15', 'Networking Lunch', 'Continue making connections for clients.', false, 6);
  insert into ros_items (project_id, day_id, time, duration, title, notes, flag, sort_order) values (pid, did, '2:00 – 2:45 PM', '45 min', 'Sessions', null, false, 7);
  insert into ros_items (project_id, day_id, time, duration, title, notes, flag, sort_order) values (pid, did, '2:45 – 3:15 PM', '30 min', 'Break', null, false, 8);
  insert into ros_items (project_id, day_id, time, duration, title, notes, flag, sort_order) values (pid, did, '3:15 – 3:45 PM', '30 min', 'Sessions', null, false, 9);
  insert into ros_items (project_id, day_id, time, duration, title, notes, flag, sort_order) values (pid, did, '3:45 – 4:00 PM', '15 min', 'Break', null, false, 10);
  insert into ros_items (project_id, day_id, time, duration, title, notes, flag, sort_order) values (pid, did, '4:00 PM', null, 'General Session', null, false, 11);
  insert into ros_items (project_id, day_id, time, duration, title, notes, flag, sort_order) values (pid, did, '5:30 – 6:30 PM', '60 min', 'Happy Hour Reception', 'Close out any remaining client connections.', false, 12);
  insert into ros_items (project_id, day_id, time, duration, title, notes, flag, sort_order) values (pid, did, '7:15 PM', null, 'Team Dinner @ Bashi', null, false, 13);
  insert into ros_items (project_id, day_id, time, duration, title, notes, flag, sort_order) values (pid, did, 'After Dinner', null, 'Departures', 'Per transcript, team departs Tuesday night. Booked flights/checkouts (Nic 7:00 AM, Caitlin 10:55 AM, Fernando 11:00 AM, Beth 4:10 PM) fall on Wed Jul 22 — confirm actual departure day.', true, 14);
  insert into ros_days (project_id, label, day_date, color, footnote, sort_order) values (pid, 'Wednesday, July 22, 2026', null, '#0F6E56', 'Per Info Hub — not covered in planning transcripts. Most booked flights/hotel checkouts (JG, Nic, Caitlin, Beth) fall on this day — reconcile against the Tuesday-night departure plan above.', 3) returning id into did;
  insert into ros_items (project_id, day_id, time, duration, title, notes, flag, sort_order) values (pid, did, '7:00 AM – 3:30 PM', '8.5 hrs', 'Tech Stands Open', null, false, 0);
  insert into ros_items (project_id, day_id, time, duration, title, notes, flag, sort_order) values (pid, did, '3:30 PM', null, 'Event Closes', null, false, 1);
